  ?zone a brick:Zone .
}

SELECT ?sensor ?point WHERE {
  ?sensor brick:hasPoint ?point .
  ?point ref:hasExternalReference ?sensor ; a brick:Air_Temperature .
  ?sensor brick:locationOf ?z .
  ?z rdfs:label "DataCenter_mid_ZN_6" ; a brick:HVAC_Zone .
}

SELECT ?point ?ts WHERE {
  ?point ref:hasTimeseriesId ?ts ; a brick:Air_Temperature .
  ?point brick:pointOf ?sensor .
  ?sensor brick:locationOf ?z .
  ?z rdfs:label "DataCenter_mid_ZN_6" ; a brick:HVAC_Zone .
}

SELECT ?thing ?pred ?obj WHERE {
  ?z rdfs:label "DataCenter_mid_ZN_6" ; a brick:HVAC_Zone .
  { ?thing ?pred ?z }
  UNION
  { ?z ?pred ?thing }
}

